// Promise job queue.
//
// Contract:
// - add(fn) queues a job; fn may return a promise, a plain value, or throw.
//   add() returns a promise that settles with the job's outcome.
// - At most `concurrency` jobs run at the same time; jobs start in the order they were added.
// - A failing job rejects its own promise only; the queue keeps going.
// - onIdle() resolves once nothing is pending and nothing is running (immediately if already idle).
// - pause() stops starting new jobs (running ones finish); resume() starts as many as there are free slots.
// - `pending` and `running` report the current counts.
function createQueue({ concurrency = 1 } = {}) {
  const pending = [];
  let running = 0;
  let paused = false;
  let idleWaiters = [];

  function next() {
    if (paused || running >= concurrency || pending.length === 0) return;
    const { fn, resolve, reject } = pending.shift();
    running++;
    fn().then((value) => {
      running--;
      resolve(value);
      next();
      checkIdle();
    }, reject);
  }

  function checkIdle() {
    if (pending.length === 0) {
      idleWaiters.forEach((wake) => wake());
      idleWaiters = [];
    }
  }

  return {
    add(fn) {
      return new Promise((resolve, reject) => {
        pending.push({ fn, resolve, reject });
        next();
      });
    },
    onIdle() {
      return new Promise((resolve) => {
        idleWaiters.push(resolve);
        checkIdle();
      });
    },
    pause() {
      paused = true;
    },
    resume() {
      paused = false;
      next();
    },
    get pending() {
      return pending.length;
    },
    get running() {
      return running;
    },
  };
}

module.exports = { createQueue };
const assert = require('assert');
const { createQueue } = require('../src/queue');

const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

test('runs jobs and returns their results', async () => {
  const q = createQueue({ concurrency: 2 });
  const results = await Promise.all([1, 2, 3].map((n) => q.add(async () => { await sleep(5); return n * 10; })));
  assert.deepStrictEqual(results, [10, 20, 30]);
});

test('starts jobs in order with concurrency 1', async () => {
  const q = createQueue();
  const order = [];
  await Promise.all(['a', 'b', 'c'].map((x) => q.add(async () => { order.push(x); await sleep(1); })));
  assert.deepStrictEqual(order, ['a', 'b', 'c']);
});
// Minimal test runner (no dependencies): `node test/run.js` runs every test/*.test.js.
// Tests may be async; each gets 5 s before it counts as hung.
const fs = require('fs');
const path = require('path');

const TIMEOUT_MS = 5000;
const tests = [];
global.test = (name, fn) => tests.push({ name, fn });
for (const f of fs.readdirSync(__dirname).filter((x) => x.endsWith('.test.js')).sort()) {
  require(path.join(__dirname, f));
}

function withTimeout(promise) {
  let timer;
  const timeout = new Promise((_, reject) => { timer = setTimeout(() => reject(new Error(`timed out after ${TIMEOUT_MS} ms`)), TIMEOUT_MS); });
  return Promise.race([promise, timeout]).finally(() => clearTimeout(timer));
}

(async () => {
  let failed = 0;
  for (const t of tests) {
    try {
      await withTimeout(Promise.resolve().then(t.fn));
      console.log(`  ✓ ${t.name}`);
    } catch (e) {
      failed++;
      console.log(`  ✗ ${t.name}`);
      console.log(`    ${String(e && e.message).split('\n').join('\n    ')}`);
    }
  }
  console.log(`\nTests: ${failed} failed, ${tests.length - failed} passed, ${tests.length} total`);
  // Exit explicitly: a hung test may leave timers or promises behind.
  process.exit(failed ? 1 : 0);
})();

